CREATE TABLE IF NOT EXISTS "roles" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(50) UNIQUE NOT NULL,
  "name" varchar(100) NOT NULL,
  "description" text,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL DEFAULT (now()),
  "updated_at" timestamp NOT NULL DEFAULT (now())
);

COMMENT ON COLUMN "roles"."code" IS 'Mã định danh vai trò (admin, driver, customer, dispatcher, v.v.)';

COMMENT ON COLUMN "roles"."name" IS 'Tên hiển thị (Quản trị viên, Tài xế, Khách hàng...)';

COMMENT ON COLUMN "roles"."description" IS 'Mô tả phạm vi quyền hạn của vai trò';

COMMENT ON COLUMN "roles"."is_active" IS 'Trạng thái kích hoạt';

